begin;
select plan(14);
insert into auth.users(id,instance_id,aud,role,email,created_at,updated_at) values
('00000000-0000-4000-8000-00000000f001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','setup-editor@example.invalid',now(),now()),
('00000000-0000-4000-8000-00000000f002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','setup-outsider@example.invalid',now(),now());
insert into public.workspaces(id,name,created_by) values ('00000000-0000-4000-8000-00000000f010','Setup contract','00000000-0000-4000-8000-00000000f001');
insert into public.workspace_memberships(workspace_id,user_id,technical_role,status) values ('00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','owner','active');
insert into public.project_states(id,workspace_id,name,stage,commercial_stage,status,priority,created_by,owner_user_id) values ('00000000-0000-4000-8000-00000000f020','00000000-0000-4000-8000-00000000f010','Setup fixture','project_authorization_setup','project_authorization_setup','active','medium','00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f001');
insert into public.authorization_records(id,project_state_id,outcome,actor_user_id) values ('00000000-0000-4000-8000-00000000f030','00000000-0000-4000-8000-00000000f020','approved','00000000-0000-4000-8000-00000000f001');
select set_config('test.setup_evidence',(select jsonb_agg(jsonb_build_object('requirement',k,'state','satisfied','details','Reviewed synthetic basis','evidenceReference','fixture:approved-record','accountableUserId','00000000-0000-4000-8000-00000000f001','materialBlocker',false))::text from unnest(private.setup_requirement_keys()) k),true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f001","role":"authenticated"}',true);
select is((public.read_project_setup('00000000-0000-4000-8000-00000000f020')->>'version')::integer,0,'new Setup starts unsaved');
select throws_ok($$select public.save_project_setup('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f040',current_setting('test.setup_evidence')::jsonb)$$,'P0001','missing_setup_edit_permission','technical owner role alone does not grant editing');
reset role;
insert into public.user_permission_overrides(workspace_id,user_id,permission_key,effect) values ('00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','project.setup.edit','grant');
set local role authenticated;
select is((public.save_project_setup('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f040',current_setting('test.setup_evidence')::jsonb)->>'version')::integer,1,'save appends version one');
select is(public.read_project_setup('00000000-0000-4000-8000-00000000f020')->'evidence',current_setting('test.setup_evidence')::jsonb,'reopen retains all evidence');
select is(public.read_project_setup('00000000-0000-4000-8000-00000000f020')->'unmet','[]'::jsonb,'readiness derived from saved accountable evidence');
select is(public.read_project_setup('00000000-0000-4000-8000-00000000f020')->>'authorizationRecordId','00000000-0000-4000-8000-00000000f030','retains frozen upstream reference');
select is((public.save_project_setup('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f040',current_setting('test.setup_evidence')::jsonb)->>'savedVersion')::integer,1,'lost response retry returns original version');
select is((select count(*)::integer from public.project_setup_versions),1,'retry appends nothing');
select throws_ok($$select public.save_project_setup('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f041',current_setting('test.setup_evidence')::jsonb)$$,'P0001','setup_version_conflict','stale editor cannot overwrite');
select throws_ok($$select public.enter_project_state_preconstruction_mobilization('00000000-0000-4000-8000-00000000f020')$$,'P0001','governed_gate01_decision_required','legacy checkbox transition cannot bypass gate');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f002","role":"authenticated"}',true);
select is((select count(*)::integer from public.project_setup_versions),0,'outsider cannot read versions');
select throws_ok($$select public.read_project_setup('00000000-0000-4000-8000-00000000f020')$$,'P0001','project_state_not_found_or_access_denied','outsider RPC rejected');
reset role;
update public.project_states set archived_at=now() where id='00000000-0000-4000-8000-00000000f020';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f001","role":"authenticated"}',true);
select throws_ok($$select public.save_project_setup('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f042',current_setting('test.setup_evidence')::jsonb)$$,'P0001','setup_edit_not_allowed','archived record cannot change');
select is(public.read_project_setup('00000000-0000-4000-8000-00000000f020')->>'canEdit','false','archived history remains read-only');
reset role;
select * from finish();
rollback;
